// Normalize Telegram webhook data and extract chat_id
const input = $input.first().json;

console.log('=== WEBHOOK RECEIVED ===');
console.log('Input keys:', Object.keys(input));
console.log('Full input (masked):', JSON.stringify(input, (key, value) => {
  if (key === 'bot_token' || key.includes('token')) {
    return value && typeof value === 'string' ? value.substring(0, 10) + '...' : value;
  }
  return value;
}, 2));

// Handle webhook wrapper - data might be in body or at root level
const webhookData = input.body || input;

console.log('Webhook data keys:', Object.keys(webhookData));

// Extract bot_token from query parameters if available
// In N8N, webhook query parameters are typically in input.query
console.log('input.query:', input.query);
console.log('input.params:', input.params);
console.log('input.bot_token:', input.bot_token);

let botTokenFromQuery = input.query?.bot_token || input.params?.bot_token || input.bot_token;
console.log("Bot token from query (initial):", botTokenFromQuery);

// Also check for query string in raw webhook data
if (!botTokenFromQuery) {
  console.log("WARNING: No bot token found in query params. Checking other locations...");
  console.log("Checking input.query string:", JSON.stringify(input.query));
  console.log("Checking input.params string:", JSON.stringify(input.params));
  console.log("Checking input.queryString:", input.queryString);
  console.log("Checking input.url:", input.url);
  console.log("Checking input.rawBody:", input.rawBody ? "exists" : "missing");

  // Try to parse URL if available
  if (input.url) {
    console.log("Attempting to parse URL:", input.url);
    try {
      const url = new URL(input.url);
      const urlParams = new URLSearchParams(url.search);
      botTokenFromQuery = urlParams.get("bot_token") || botTokenFromQuery;
      console.log("Bot token from URL parsing:", botTokenFromQuery);
    } catch (err) {
      console.log("Error parsing URL:", err.message);
    }
  }
}

// Store bot token for later database lookup
const botTokenForDbLookup = botTokenFromQuery;

// Extract chat_id from message
let chatId = null;
let telegramUserId = null;
let text = null;
let callbackData = null;
let callbackQueryId = null;
let messageId = null;
let photo = null;
let document = null;
let isPDF = false;

if (webhookData.message) {
  // Direct Telegram format
  const message = webhookData.message;
  chatId = message.chat?.id;
  telegramUserId = message.from?.id;
  text = message.text;
  messageId = message.message_id;

  // Check for photo
  if (message.photo && message.photo.length > 0) {
    photo = message.photo;
    console.log('Photo detected:', photo.length, 'sizes');
  }

  // Check for document (could be PDF or other file)
  if (message.document) {
    document = message.document;
    const mimeType = document.mime_type || '';
    isPDF = mimeType === 'application/pdf' || mimeType === 'application/x-pdf';
    console.log('Document detected:', document.file_name, 'MIME:', mimeType, 'isPDF:', isPDF);
  }
} else if (webhookData.callback_query) {
  // Callback query (button press)
  const callbackQuery = webhookData.callback_query;
  chatId = callbackQuery.message?.chat?.id;
  telegramUserId = callbackQuery.from?.id;
  callbackData = callbackQuery.data;
  callbackQueryId = callbackQuery.id;
  messageId = callbackQuery.message?.message_id;
  text = callbackQuery.message?.text;
  console.log('Callback query detected:', callbackData);
}

// Debug output
console.log('=== EXTRACTED DATA ===');
console.log('chatId:', chatId, 'type:', typeof chatId);
console.log('telegramUserId:', telegramUserId, 'type:', typeof telegramUserId);
console.log('text:', text);
console.log('callbackData:', callbackData);
console.log('photo exists:', !!photo);
console.log('document exists:', !!document);
console.log('isPDF:', isPDF);

// Ensure chat_id is a string for database lookup (to match PostgreSQL text type)
const chatIdString = chatId !== null ? String(chatId) : null;
const telegramUserIdString = telegramUserId !== null ? String(telegramUserId) : null;

// Return normalized data
return {
  json: {
    chat_id: chatIdString,
    telegram_user_id: telegramUserIdString,
    text: text,
    callback_data: callbackData,
    callback_query_id: callbackQueryId,
    message_id: messageId,
    photo: photo,
    document: document,
    is_pdf: isPDF,
    bot_token_from_webhook_raw: botTokenForDbLookup,
    bot_token_from_webhook: botTokenForDbLookup ? botTokenForDbLookup.replace(/\\/g, '\\\\').replace(/'/g, "''") : null,
    original_webhook_data: webhookData
  }
};

// Merge normalized data with bot token from database
const normalizedData = $('Normalize Telegram Data').first().json;
const dbResult = $input.first().json;

console.log('=== MERGE BOT TOKEN ===');
console.log('DB Result:', dbResult);
console.log('Bot token from webhook (raw):', normalizedData.bot_token_from_webhook_raw);
console.log('Bot token from webhook (escaped):', normalizedData.bot_token_from_webhook);
console.log('Chat ID from normalized data:', normalizedData.chat_id);

// If database lookup failed but we have bot_token from webhook, use it
if (!dbResult || !dbResult.telegram_bot_token) {
  if (normalizedData.bot_token_from_webhook_raw) {
    console.log('WARNING: No user found for chat_id:', normalizedData.chat_id);
    console.log('But we have bot_token from webhook. This might be a new user.');
    console.log('They need to send /start with token to link their account.');

    // We still can't proceed without a user_id for expense tracking
    // But we have the bot_token which we can use to send error messages
    return {
      json: {
        ...normalizedData,
        bot_token: normalizedData.bot_token_from_webhook_raw,  // Use raw for API calls
        bot_username: null,
        user_id: null,  // Database user_id (for INSERT into expenses table)
        error: true,
        error_message: 'User not registered or bot token not configured. Please send /start with your token.',
        needs_start_command: true
      }
    };
  } else {
    console.log('WARNING: No bot token found for chat_id:', normalizedData.chat_id);
    return {
      json: {
        ...normalizedData,
        bot_token: null,
        bot_username: null,
        user_id: null,  // Database user_id (for INSERT into expenses table)
        error: true,
        error_message: 'User not registered or bot token not configured'
      }
    };
  }
}

console.log('Bot token found for user:', dbResult.user_id);

// Important: Use database bot_token for API calls, not the webhook one
return {
  json: {
    ...normalizedData,
    user_id: dbResult.user_id,  // ✅ Database user_id (users.id) - USE THIS FOR EXPENSE INSERTS
    bot_token: dbResult.telegram_bot_token,  // Database bot_token for Telegram API calls
    bot_username: dbResult.telegram_bot_username,
    error: false
  }
};

